"""Text-to-SQL harness: draft query, execute-check, one evidence-rich repair call.

Contract (fixed): solve(task, env) -> {"sql": str}
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
IDENT = re.compile(r"[A-Za-z_][A-Za-z_0-9]*")
STOP = set(
    """a an the of for in on at to and or not with without by from as is are was were be been being
    that this these those it its their his her they them there here which what who whom whose when
    where how why all any each every both either neither some many much most more least few than
    then also only just do does did done have has had having can could may might must will would
    shall should if but so such same other another into out up down over under between among
    about against during before after above below no nor none never always ever list show find
    give tell get name names id ids number count total average sum minimum maximum min max
    first last second third next previous top bottom highest lowest greatest smallest oldest
    youngest newest latest best worst long short big small large great good bad new old
    please me you your we our us i he she him hers mine yours theirs ours
    select distinct from where group order limit asc desc join inner left right full outer cross
    union intersect except exists case end else null true false like between using natural
    sqlite sql query database table column row rows value values result results return output
    """.split()
)


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    return (text or "").strip().rstrip(";").strip()


def _schema_tables(schema):
    """Return {table_name: [(col_name, col_type), ...]} parsed from CREATE statements."""
    tables = {}
    for m in re.finditer(r"CREATE\s+TABLE\s+[`\"]?(\w+)[`\"]?\s*\((.*)\)", schema, re.S | re.I):
        name, body = m.group(1), m.group(2)
        cols = []
        depth = 0
        cur = ""
        parts = []
        for ch in body:
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
            if ch == "," and depth == 0:
                parts.append(cur)
                cur = ""
            else:
                cur += ch
        parts.append(cur)
        for p in parts:
            p = p.strip()
            if not p:
                continue
            first = p.split()[0].strip('`"[]')
            if first.upper() in ("PRIMARY", "FOREIGN", "UNIQUE", "CHECK", "CONSTRAINT"):
                continue
            typ = p.split()[1].upper() if len(p.split()) > 1 else ""
            cols.append((first, typ))
        tables[name] = cols
    return tables


def _fk_pairs(schema):
    """[(child_table, child_col, parent_table, parent_col)] from FOREIGN KEY clauses."""
    out = []
    for m in re.finditer(r"CREATE\s+TABLE\s+[`\"]?(\w+)[`\"]?\s*\((.*)\)", schema, re.S | re.I):
        tname, body = m.group(1), m.group(2)
        for f in re.finditer(
            r"FOREIGN\s+KEY\s*\(\s*[`\"\[]?(\w+)[`\"\]]?\s*\)\s*REFERENCES\s+"
            r"[`\"\[]?(\w+)[`\"\]]?\s*\(\s*[`\"\[]?(\w+)[`\"\]]?\s*\)",
            body,
            re.I,
        ):
            out.append((tname, f.group(1), f.group(2), f.group(3)))
    return out


def _is_text(ctype):
    return any(k in ctype for k in ("CHAR", "TEXT", "CLOB")) or ctype == ""


def _sample(env, tname, cname, n_vals=10):
    try:
        r = env.execute(
            f'SELECT DISTINCT "{cname}" FROM "{tname}" WHERE "{cname}" IS NOT NULL LIMIT {n_vals}'
        )
    except Exception:
        return None
    if not r.get("ok") or not r.get("rows"):
        return None
    vals = [str(row[0])[:60] for row in r["rows"]]
    return f"{tname}.{cname}: " + ", ".join(repr(v) for v in vals)


def _value_samples(task, env, schema, sql="", max_lines=14):
    """Sample stored values of text columns likely to matter.

    Priority: (1) columns referenced in the draft SQL, (2) columns whose name
    tokens overlap the question/hint, (3) foreign-key / relation columns of
    tables mentioned in the question or SQL (their names often share no words
    with the question, e.g. a link table's two id columns).
    """
    text = (task.get("question", "") + " " + (task.get("hint") or "")).lower()
    qwords = set(IDENT.findall(text)) - STOP
    swords = set(IDENT.findall((sql or "").lower())) - STOP
    tables = _schema_tables(schema)
    lower_map = {t.lower(): t for t in tables}
    mentioned = set()
    for w in qwords | swords:
        if w in lower_map:
            mentioned.add(lower_map[w])
        elif w + "s" in lower_map:
            mentioned.add(lower_map[w + "s"])
        elif w.endswith("s") and w[:-1] in lower_map:
            mentioned.add(lower_map[w[:-1]])

    fk_cols = {}
    for ct, cc, pt, pc in _fk_pairs(schema):
        fk_cols.setdefault(ct, set()).add(cc.lower())
        fk_cols.setdefault(pt, set()).add(pc.lower())

    scored = []
    for tname, cols in tables.items():
        tmention = tname in mentioned
        for cname, ctype in cols:
            if not _is_text(ctype):
                continue
            cl = cname.lower()
            toks = set(re.split(r"[_\s]+", cl)) - STOP
            score = 0
            if cl in swords or (toks & swords):
                score += 4
            if cl in qwords or (toks & qwords):
                score += 3
            if tmention:
                score += 1
            if cl in fk_cols.get(tname, ()) and (tmention or cl in swords):
                score += 3
            if score > 0:
                scored.append((score, tname, cname))
    scored.sort(key=lambda x: (-x[0], x[1], x[2]))

    out = []
    seen = set()
    for _, tname, cname in scored:
        if len(out) >= max_lines:
            break
        key = (tname, cname)
        if key in seen:
            continue
        seen.add(key)
        s = _sample(env, tname, cname)
        if s:
            out.append(s)
    return "\n".join(out)


def _empty_diagnostics(env, schema, sql):
    """Cheap, generic probes explaining why a valid query returned no rows."""
    lines = []
    tables = _schema_tables(schema)
    lower_map = {t.lower(): t for t in tables}
    # Tables appearing in the SQL, with their equality filters.
    for m in re.finditer(
        r"(?:FROM|JOIN)\s+[`\"]?(\w+)[`\"]?(?:\s+(?:AS\s+)?([A-Za-z_]\w*))?", sql, re.I
    ):
        raw, alias = m.group(1), (m.group(2) or "")
        if alias.upper() in ("ON", "WHERE", "GROUP", "ORDER", "LEFT", "INNER", "JOIN", "LIMIT", "USING", "SET"):
            alias = ""
        tname = lower_map.get(raw.lower())
        if not tname:
            continue
        try:
            r = env.execute(f'SELECT COUNT(*) FROM "{tname}"')
            if r.get("ok") and r.get("rows"):
                lines.append(f"Row count of {tname}: {r['rows'][0][0]}")
        except Exception:
            pass
        quals = [alias, raw] if alias else [raw]
        for q in quals:
            for f in re.finditer(
                rf"\b{re.escape(q)}\.[`\"]?(\w+)[`\"]?\s*=\s*'([^']*)'", sql, re.I
            ):
                col, lit = f.group(1), f.group(2)
                probe = (
                    f'SELECT COUNT(*) FROM "{tname}" WHERE "{col}" = \'{lit}\''
                )
                try:
                    r = env.execute(probe)
                    if r.get("ok") and r.get("rows") and r["rows"][0][0] == 0:
                        lines.append(
                            f"No row in {tname} has {col} = '{lit}' — this literal does not exist; "
                            f"use the sampled values below."
                        )
                except Exception:
                    pass
    # NOT IN over an empty subquery makes the whole predicate false.
    for m in re.finditer(r"NOT\s+IN\s*\(\s*(SELECT\b.*?\))\s*(?:$|\)|AND|OR|ORDER|GROUP|LIMIT)",
                         sql, re.I | re.S):
        sub = m.group(1).rstrip(")")
        try:
            r = env.execute(sub)
            if r.get("ok") and r.get("n_rows", 0) == 0:
                lines.append(
                    "A NOT IN (...) subquery returned 0 rows — check that its table/column names "
                    "are the real ones in the schema (an empty or wrong subquery breaks the exclusion)."
                )
            elif not r.get("ok"):
                lines.append(f"A NOT IN (...) subquery is invalid: {r.get('error', '')}")
        except Exception:
            pass
    return "\n".join(lines[:8])


def solve(task, env):
    schema = env.schema(task["db_id"])
    user = f"Database: {task['db_id']}\n\nSchema:\n{schema}\n\nQuestion: {task['question']}"
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"
    descs = ""
    try:
        descs = env.descriptions(task["db_id"]) or ""
    except Exception:
        pass
    if descs:
        user += f"\nColumn descriptions:\n{descs}"

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    max_tokens = env.config.get("max_tokens", 800)
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)

    # Verify the draft; repair once if it fails or returns nothing.
    try:
        res = env.execute(sql)
    except Exception:
        res = {"ok": False, "error": "execution failed"}
    needs_repair = (not res.get("ok")) or res.get("n_rows", 0) == 0
    if needs_repair:
        if not res.get("ok"):
            feedback = f"The query failed with error: {res.get('error', 'unknown error')}"
        else:
            feedback = (
                "The query executed but returned 0 rows. Likely causes: a string literal that does not "
                "match the stored values exactly (singular/plural, case, spacing, abbreviations), a wrong "
                "or non-existent column in a join/subquery, or an over-restrictive filter."
            )
        diag, samples = "", ""
        try:
            if res.get("ok"):
                diag = _empty_diagnostics(env, schema, sql)
        except Exception:
            diag = ""
        try:
            samples = _value_samples(task, env, schema, sql=sql)
        except Exception:
            samples = ""
        repair_user = f"Your draft query was:\n```sql\n{sql}\n```\n{feedback}\n"
        if diag:
            repair_user += f"\nDiagnostics:\n{diag}\n"
        if samples:
            repair_user += f"\nActual stored values of relevant columns (use these exact spellings):\n{samples}\n"
        repair_user += (
            "\nWrite a corrected SQLite query for the original question. Rules for the fix:\n"
            "- Replace filter literals with the exact stored spelling shown above (e.g. singular vs plural); "
            "use LIKE '%...%' only when the question says a text 'includes'/'contains' something.\n"
            "- Every table and column you reference must appear in the schema; for link/relation tables use "
            "their real column names (shown above), not guessed ones.\n"
            "- Keep the projection the question asks for: if it names an entity without naming attributes "
            "('Which countries/students ...'), select all columns of that entity's table.\n"
            "Return only one ```sql code block."
        )
        messages.append({"role": "assistant", "content": reply})
        messages.append({"role": "user", "content": repair_user})
        try:
            reply2 = env.chat(messages, max_tokens=max_tokens)
            sql2 = extract_sql(reply2)
            if sql2:
                try:
                    res2 = env.execute(sql2)
                except Exception:
                    res2 = {"ok": False}
                if res2.get("ok") and (res2.get("n_rows", 0) > 0 or not res.get("ok")):
                    sql = sql2
        except Exception:
            pass

    return {"sql": sql}

proposal.raw:
**Diagnosis of the three remaining failures (all "runs fine, wrong answer" cases):**

- `sp0536`: filter column *name* matched the question ("Bachelors program") but stored values are `'Bachelor'` → 0 rows. The repair sampler only samples columns whose **name tokens overlap the question**, so `degree_summary_name` was never sampled and the model had no way to discover the real literal.
- `sp0894`: `Friend(student_id, friend_id)` — none of those name tokens appear in "students who do not have any friends", so the relation table's columns were never sampled and the model invented non-existent column names. Also, a `NOT IN` over an empty subquery silently returns 0 rows with no error.
- `sp0755`: projection failure — "Which countries ..." requires all entity columns; the prompt already says this but the model still projected one column, and nothing checks it.

So the weakness the frequent pattern hides is **diagnostic coverage**: sampling keyed on question words misses exactly the columns that cause silent-empty results (filter columns actually used in the SQL, and FK/relation columns). Two edits: broaden evidence gathering + empty-result diagnostics in `solve.py`, and tighten projection/anti-join guidance in the prompt.

